import { test as base } from '@playwright/test'
import {
  bookingSuccessResponse,
  EVENTS_BOOKING_URL,
  EVENTS_COUNTER_URL,
  EVENTS_URL,
  rawCounterFixture,
  rawEventsFixture,
} from '../mocks/handlers/events'
import { formsSuccessResponse, NEWS_SUBSCRIBE_URL, NEWS_UNSUBSCRIBE_URL } from '../mocks/handlers/forms'

const BACKEND_API = process.env.BACKEND_API || 'http://backend.test'

const HCAPTCHA_JS_URL = 'https://js.hcaptcha.com/1/api.js*'

const hcaptchaMockScript = `
  window.hcaptcha = {
    render: (container, config) => {
      const id = 'hcaptcha-' + Math.random().toString(36).slice(2)
      return id
    },
    getResponse: (id) => 'test-token',
    getRespKey: (id) => 'test-ekey',
    execute: (id) => {},
    execute: (id, options) => {
      if (options && options.async) {
        return Promise.resolve({ response: 'test-token', key: 'test-ekey' })
      }
    },
    reset: (id) => {},
    close: (id) => {},
  }
`

export const test = base.extend<{
  backend: {
    booking: { body: Record<string, unknown>; token: string }[]
    membership: { body: Record<string, unknown>; token: string }[]
    news: { body: Record<string, unknown>; subscribe: boolean }[]
  }
}>({
  backend: async ({ page }, use) => {
    const backend = {
      booking: [] as { body: Record<string, unknown>; token: string }[],
      membership: [] as { body: Record<string, unknown>; token: string }[],
      news: [] as { body: Record<string, unknown>; subscribe: boolean }[],
    }

    await page.route(HCAPTCHA_JS_URL, (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/javascript',
        body: hcaptchaMockScript,
      })
    })

    await page.route(`${BACKEND_API}/events`, (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify(rawEventsFixture),
      })
    })

    await page.route(`${BACKEND_API}/events/counter`, (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify([rawCounterFixture]),
      })
    })

    await page.route(`${BACKEND_API}/events/booking`, async (route, request) => {
      const body = (await request.postDataJSON()) as Record<string, unknown>
      backend.booking.push({ body, token: String(body.token ?? '') })
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify(bookingSuccessResponse),
      })
    })

    await page.route(`${BACKEND_API}/membership/application`, async (route, request) => {
      const body = (await request.postDataJSON()) as Record<string, unknown>
      backend.membership.push({ body, token: String(body.token ?? '') })
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ success: true }),
      })
    })

    await page.route(`${BACKEND_API}/news/subscribe`, async (route, request) => {
      const body = (await request.postDataJSON()) as Record<string, unknown>
      backend.news.push({ body, subscribe: true })
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify(formsSuccessResponse),
      })
    })

    await page.route(`${BACKEND_API}/news/unsubscribe`, async (route, request) => {
      const body = (await request.postDataJSON()) as Record<string, unknown>
      backend.news.push({ body, subscribe: false })
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify(formsSuccessResponse),
      })
    })

    await page.route(`${BACKEND_API}/contact/message`, (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify(formsSuccessResponse),
      })
    })

    await use(backend)
  },
})

export const expect = test.expect

export async function assertNotification(
  page: Parameters<typeof test>[0],
  title: string,
  message: string,
) {
  const notification = page.locator('#notification-popup')
  await expect(notification).toBeVisible()
  await expect(notification.locator('#title')).toHaveText(title)
  await expect(notification.locator('#message')).toHaveText(message)
}

